const errorData = $input.first().json;

const workflow = errorData.workflow || {};
const execution = errorData.execution || {};
const errorObj = execution.error || {};

const workflowName = workflow.name || 'Unknown Workflow';
const workflowId = workflow.id || 'N/A';
const executionId = execution.id || 'N/A';
const lastNode = execution.lastNodeExecuted || 'Unknown Node';
const errorMessage = errorObj.message || 'Workflow execution failed';
const errorStack = errorObj.stack || '';

// Determine Auto-Remediation Strategy
let remediationStrategy = 'NONE';
let isTransient = false;

if (errorMessage.includes('ECONNREFUSED') || errorMessage.includes('ETIMEDOUT')) {
  remediationStrategy = 'RESTART_TARGET_CONTAINER';
  isTransient = true;
} else if (errorMessage.includes('429') || errorMessage.includes('rate limit')) {
  remediationStrategy = 'RATE_LIMIT_BACKOFF';
  isTransient = true;
} else if (errorMessage.includes('JWT') || errorMessage.includes('401')) {
  remediationStrategy = 'REFRESH_AUTH_TOKEN';
}

return {
  workflow_name: workflowName,
  workflow_id: workflowId,
  execution_id: executionId,
  last_node: lastNode,
  error_message: errorMessage,
  remediation_strategy: remediationStrategy,
  is_transient: isTransient,
  timestamp: new Date().toISOString(),
  payload: {
    workflow: workflow,
    execution_id: executionId,
    last_node: lastNode,
    error: errorMessage,
    stack_snippet: errorStack.split('\n').slice(0, 5).join('\n')
  }
};
